import{_ as i,l as n,o as e,c as r,v as o,p as d,x as l,d as s,i as B,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"动态面板 Arellano–Bond","description":"","frontmatter":{"title":"动态面板 Arellano–Bond","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/arellano-bond.md","filePath":"econ/arellano-bond.md","lastUpdated":1789023840000}'),_={name:"econ/arellano-bond.md"};function E(p,a,h,A,m,u){const t=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="动态面板-arellano–bond" tabindex="-1">动态面板 Arellano–Bond <a class="header-anchor" href="#动态面板-arellano–bond" aria-label="Permalink to &quot;动态面板 Arellano–Bond&quot;">​</a></h1><div class="epigraph"><p>$T$ 短、$N$ 大、方程里有滞后 $Y$ 时，组内去均值让滞后项与误差相关；差分后用更早的水平当工具，是 Arellano–Bond 的处方，不是再加一年虚拟变量。</p><footer>—— Nickell, Biases in Dynamic Models with Fixed Effects, Econometrica 1981；Arellano and Bond, Some Tests of Specification for Panel Data, RES 1991</footer></div><p><a href="/econ/fe-re">上一课</a>在严格外生下用 FE 吸掉 \\(c_i\\)。本课缺口是动态：\\(Y_{it}=\\rho Y_{i,t-1}+X_{it}\\beta+c_i+u_{it}\\)。Nickell：within 之后 \\(\\rho\\) 的偏误阶为 \\(1/T\\)，短面板不可忽略。异质处理效应下一课回到因果参数本身；本课先把动态面板的工具装置钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>滞后 \\(Y\\) 含 \\(c_i\\)，FE 去均值让 \\(\\tilde Y_{i,t-1}\\) 与 \\(\\tilde u_{it}\\) 相关。\\(T\\to\\infty\\) 偏误消失，公司金融与宏观国别面板往往 \\(T\\) 二三十，\\(N\\) 大，正是 Nickell 区域。一阶差分消去 \\(c_i\\)：</p> \\[\\Delta Y_{it}=\\rho\\Delta Y_{i,t-1}+\\Delta X_{it}\\beta+\\Delta u_{it}. \\]<p>\\(\\Delta Y_{i,t-1}\\) 仍与 \\(\\Delta u_{it}\\) 相关（因为 \\(Y_{i,t-1}\\) 含 \\(u_{i,t-1}\\)）。若 \\(u\\) 无序列相关，\\(Y_{i,t-2}\\) 及更早水平与 \\(\\Delta u_{it}\\) 不相关、与 \\(\\Delta Y_{i,t-1}\\) 相关，于是可当工具。这是 Arellano–Bond（差分 GMM）。缺口是：工具个数随 \\(T\\) 爆炸，弱工具与过度识别同时来——上一课序的警告在这里最狠。</p><p><span class="marginnote">Blundell–Bond 系统 GMM：再加水平方程，用差分当工具，改善 \\(\\rho\\) 接近 1 时差分工具弱。前提是平稳与均值平稳的初始条件，不是免费午餐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一步 / 两步 GMM，Windmeijer 有限样本校正两步标准误。Hansen \\(J\\) 检验过度识别；AR(2) 检验差分残差的二阶相关（一阶相关是差分的代数，AR(1) 拒绝不说明失败）。工具崩溃：限制滞后深度、塌缩工具。Roodman 的「too many instruments」是操作红线。</p>',10)),(e(),d(c,null,{default:l(()=>[B(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAG%5B%22%E6%BB%9E%E5%90%8E%20Y%20%2B%20c_i%22%5D%20--%3E%20NIC%5B%22Nickell%3A%20within%20%E5%81%8F%E8%AF%AF%22%5D%0A%20%20DIF%5B%22%E4%B8%80%E9%98%B6%E5%B7%AE%E5%88%86%22%5D%20--%3E%20AB%5B%22%E6%B0%B4%E5%B9%B3%E6%BB%9E%E5%90%8E%E5%BD%93%E5%B7%A5%E5%85%B7%22%5D%0A%20%20AB%20--%3E%20MANY%5B%22T%20%E5%8D%87%3A%20%E5%B7%A5%E5%85%B7%E7%88%86%E7%82%B8%22%5D%0A%20%20MANY%20--%3E%20WEAK%5B%22%E5%BC%B1%E5%B7%A5%E5%85%B7%20%2B%20J%20%E5%A4%B1%E6%95%88%22%5D%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%20GMM%22%5D%20--%3E%20INIT%5B%22%E8%A6%81%E5%88%9D%E5%A7%8B%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>\\(X\\) 若前定或内生，工具滞后结构要跟着改，不能把所有 \\(X\\) 当严格外生。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制仍是 IV：差分把 \\(c_i\\) 去掉，时间上的前定把更早的 \\(Y\\) 变成合法 \\(Z\\)。序列相关一出现，滞后就不再排除——投资、工资的持久冲击会让 AR(2) 拒绝。\\(\\rho\\) 近单位根时差分几乎不提供变异，第一阶段弱，估计坍向有偏。系统 GMM 用水平方程找回变异，把假设从「无相关」换成「对初始偏差的限制」。</p><p>与<a href="/econ/lucas-critique">卢卡斯批判</a>：\\(\\rho\\) 是简化式持续，政策规则变了可以变。GMM 一致不等于结构消费欧拉。宏观估计消费习惯或调整成本，要另写欧拉，不能把 Arellano–Bond 的 \\(\\rho\\) 直接当深层参数。</p><p><span class="marginnote">公司金融的滞后杠杆回归是高频用户。工具是滞后资本结构，排除故事弱，弱工具常见。本课给装置，不重做那些表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推荐「默认系统 GMM 加全部滞后」。不处理异质 \\(\\rho_i\\)（Pesaran 一类平均组）。\\(T\\) 大时偏误小，可以直接 FE 加稳健推断，不必 GMM。下一课把「\\(\\beta\\) 对谁」的异质从动态装置里抽出来单独讲。</p><p>后课默认：短面板动态先承认 Nickell；差分 GMM 要 AR(2)、工具计数与崩溃诊断。系统 GMM 必须写初始条件。不要用动态 GMM 替代<a href="/econ/staggered-did">交错 DiD</a> 的干净对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nickell：FE + 滞后 \\(Y\\)，短 \\(T\\) 下 \\(\\rho\\) 有偏。</li><li>Arellano–Bond：差分后用更早水平当工具。</li><li>工具随 \\(T\\) 爆炸则弱、则 \\(J\\) 不可信；要崩溃。</li><li>系统 GMM 改善弱差分，但吃初始条件。</li><li>出处：Nickell, <em>Econometrica</em> 1981；Arellano and Bond, <em>RES</em> 1991；Blundell and Bond；Roodman 工具过多。</li></ul>',10))])}const M=i(_,[["render",E]]);export{D as __pageData,M as default};
